g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "x": 80, "y": 760, "width": 1080, "height": 680,
  "name": "risk-register",
  "header_rows": 1,
  "column_widths": [60, 260, 130, 110, 380, 140],
  "row_heights": [50, 110, 140, 80, 80, 110, 110],
  "defaults": {
    "cell": {
      "valign": "top",
      "align": "l",
      "padding": {"left": 8, "right": 8, "top": 10, "bottom": 10},
      "borders": {
        "left": {"style": "none"},
        "right": {"style": "none"},
        "top": {"style": "none"},
        "bottom": {"style": "solid", "color": "#E7E3DB", "width": 1}
      }
    },
    "run": {"color": "#16232E"}
  },
  "columns": [
    {"text": "#", "bold": true, "font_size": 20, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}},
    {"text": "Risk", "bold": true, "font_size": 20, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}},
    {"text": "Likelihood", "bold": true, "font_size": 20, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}},
    {"text": "Impact", "bold": true, "font_size": 20, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}},
    {"text": "Mitigation", "bold": true, "font_size": 20, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}},
    {"text": "Owner", "bold": true, "font_size": 20, "borders": {"left": {"style": "none"}, "right": {"style": "none"}, "top": {"style": "none"}, "bottom": {"style": "solid", "color": "#16232E", "width": 2}}}
  ],
  "rows": [
    ["1", "Client and stakeholder expectations (F028 · F037)", {"text": "High", "color": "#B4471C"}, {"text": "High", "color": "#B4471C"}, "Client communication agreed in Phase 0; stated response times unchanged", "Practice heads"],
    ["2", "Hours creep: a nominal 32-hour week worked as 34–36 (F011 · F040)", {"text": "High", "color": "#B4471C"}, {"text": "Medium", "color": "#4A6B7C"}, "Measure actual hours, not the policy; treat creep as a kill-criterion input", "COO"],
    ["3", "No agreed definition of productivity (F047)", {"text": "Medium", "color": "#4A6B7C"}, {"text": "High", "color": "#B4471C"}, "Metrics fixed in Phase 0 and published before the pilot starts", "Finance director"],
    ["4", "Benefit fade after month 3 (F043)", {"text": "Medium", "color": "#4A6B7C"}, {"text": "Medium", "color": "#4A6B7C"}, "Gate A is the high-water mark; the six-month read decides", "HR director"],
    ["5", "Entitlement dispute on withdrawal (F025)", {"text": "Medium", "color": "#4A6B7C"}, {"text": "Medium", "color": "#4A6B7C"}, "Non-contractual status stated in writing and acknowledged by each participant", "HR director"],
    ["6", "Inequitable application across a small team (F028)", {"text": "Medium", "color": "#4A6B7C"}, {"text": "Medium", "color": "#4A6B7C"}, "Whole-practice-group scope rather than individual opt-in", "Practice heads"]
  ],
  "style": {
    "font_family": "Arial",
    "font_size": 22,
    "header_font_size": 20,
    "header_fill": "#F2F0EB",
    "header_text": "#16232E",
    "body_text": "#16232E",
    "band_row": false
  }
}
